def bottom_up_level_order(root):
    from collections import deque
    if root is None:
        return []
    queue, answer = deque([root]), []
    while queue:
        row = []
        for _ in range(len(queue)):
            node = queue.popleft()
            row.append(node.val)
            if node.left:
                queue.append(node.left)
            if node.right:
                queue.append(node.right)
        answer.append(row)
    return answer[::-1]

